effect.shader:
float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

void main() {
    int n = clamp(int(samples), 4, 24);
    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 24; i++) {
        if (i > n) break;
        float fi = float(i) + seed * 11.0;
        vec2 j = vec2(
            hash21(acScreenNorm * acResolution + vec2(fi, 0.0)) - 0.5,
            hash21(acScreenNorm * acResolution + vec2(0.0, fi + 7.0)) - 0.5
        ) * spread;
        soma += texture(inputImg, acScreenNorm + j);
    }
    fragColor = soma / float(n + 1);
}
